def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the rectangle containing the 1-background canvas.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    a, b = r1 - r0 + 1, c1 - c0 + 1
    canvas = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    inside = {}
    outside = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 1):
                continue
            if r0 <= r <= r1 and c0 <= c <= c1:
                inside.setdefault(color, []).append((r - r0, c - c0))
            else:
                outside.setdefault(color, []).append((r, c))

    # Paired singleton colors mark the three corners that determine orientation.
    colors = [color for color in inside
              if len(inside[color]) == 1 and len(outside.get(color, [])) == 1]
    if len(colors) >= 3:
        colors = colors[:3]
        points = {color: outside[color][0] for color in colors}
        minr = min(p[0] for p in points.values())
        maxr = max(p[0] for p in points.values())
        minc = min(p[1] for p in points.values())
        maxc = max(p[1] for p in points.values())

        target = {}
        for color, (r, c) in points.items():
            target[color] = (
                0 if r == minr else a - 1,
                0 if c == minc else b - 1
            )

        transforms = [
            (a, b, lambda r, c: (r, c)),
            (a, b, lambda r, c: (a - 1 - r, c)),
            (a, b, lambda r, c: (r, b - 1 - c)),
            (a, b, lambda r, c: (a - 1 - r, b - 1 - c)),
            (b, a, lambda r, c: (c, r)),
            (b, a, lambda r, c: (c, a - 1 - r)),
            (b, a, lambda r, c: (b - 1 - c, r)),
            (b, a, lambda r, c: (b - 1 - c, a - 1 - r)),
        ]

        for oh, ow, mapping in transforms:
            matches = True
            for color in colors:
                rr, cc = mapping(*inside[color][0])
                tr, tc = target[color]
                expected = (0 if tr == 0 else oh - 1,
                            0 if tc == 0 else ow - 1)
                if (rr, cc) != expected:
                    matches = False
                    break
            if matches:
                out = [[0] * ow for _ in range(oh)]
                for r in range(a):
                    for c in range(b):
                        rr, cc = mapping(r, c)
                        out[rr][cc] = canvas[r][c]
                return out

    return canvas
